from .ranges import RangeError, parse


def _not_satisfiable(length):
    return 416, {
        'Content-Length': '0',
        'Content-Range': 'bytes */%d' % length,
    }, b''


def serve(data, range_header=None):
    length = len(data)
    if range_header is None:
        return 200, {'Content-Length': str(length)}, data

    try:
        kind, *values = parse(range_header)
    except RangeError:
        return _not_satisfiable(length)

    if kind == 'suffix':
        count = values[0]
        if count == 0 or length == 0:
            return _not_satisfiable(length)
        first = length - count if count < length else 0
        last = length - 1
    else:
        start, end = values[0], values[1] if kind == 'full' else length - 1
        if start >= length:              # start beyond (or at) EOF, incl. empty data
            return _not_satisfiable(length)
        last = end if end < length else length - 1   # clamp end past EOF
        first = start
        if first > last:                 # reverse bounds
            return _not_satisfiable(length)

    body = data[first:last + 1]          # end is inclusive
    return 206, {
        'Content-Length': str(len(body)),
        'Content-Range': 'bytes %d-%d/%d' % (first, last, length),
    }, body
